const body = $input.first().json.body || {};

if (!body.startDate || !body.endDate) {
  throw new Error('Missing startDate or endDate');
}

return {
  json: {
    calendarId: body.calendarId || 'primary',
    timeMin: body.startDate + 'T00:00:00Z',
    timeMax: body.endDate + 'T23:59:59Z',
    workStart: body.workStart || '09:00',
    workEnd: body.workEnd || '17:00',
    slotDuration: body.slotDurationMinutes || 30,
    timezone: body.timezone || 'UTC',
    useAI: body.useAI !== false
  }
};

const response = $input.first().json;
const events = response.items || [];
const params = $('Prepare Find Parameters').first().json;
const workStart = params.workStart;
const workEnd = params.workEnd;
const slotDuration = params.slotDuration;

const [startHour, startMin] = workStart.split(':').map(Number);
const [endHour, endMin] = workEnd.split(':').map(Number);

function hasOverlap(slotStart, slotEnd, events) {
  return events.some(event => {
    if (!event.start || !event.end) return false;
    const eventStart = new Date(event.start.dateTime || event.start.date);
    const eventEnd = new Date(event.end.dateTime || event.end.date);
    return slotStart < eventEnd && slotEnd > eventStart;
  });
}

const startDate = new Date(params.timeMin);
const endDate = new Date(params.timeMax);
const freeSlots = [];
let currentDay = new Date(startDate);

while (currentDay <= endDate) {
  const dayStart = new Date(currentDay);
  dayStart.setUTCHours(startHour, startMin, 0, 0);
  const dayEnd = new Date(currentDay);
  dayEnd.setUTCHours(endHour, endMin, 0, 0);
  let slotStart = new Date(dayStart);

  while (slotStart < dayEnd) {
    const slotEnd = new Date(slotStart.getTime() + slotDuration * 60000);
    if (slotEnd <= dayEnd && !hasOverlap(slotStart, slotEnd, events)) {
      freeSlots.push({
        start: slotStart.toISOString(),
        end: slotEnd.toISOString(),
        date: slotStart.toISOString().split('T')[0],
        time: `${slotStart.getUTCHours().toString().padStart(2, '0')}:${slotStart.getUTCMinutes().toString().padStart(2, '0')}`,
        dayOfWeek: ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][slotStart.getUTCDay()]
      });
    }
    slotStart = slotEnd;
  }
  currentDay.setDate(currentDay.getDate() + 1);
}

return {
  json: {
    success: true,
    totalEvents: events.length,
    totalFreeSlots: freeSlots.length,
    freeSlots: freeSlots,
    useAI: params.useAI,
    parameters: {
      workHours: `${workStart} - ${workEnd}`,
      slotDuration: `${slotDuration} minutes`,
      dateRange: `${params.timeMin.split('T')[0]} to ${params.timeMax.split('T')[0]}`
    }
  }
};

// Prepare Groq Request - Function Node
const data = $input.first().json;
const slots = data.freeSlots || [];
const sampleSlots = slots.slice(0, 10);

// Build request body as OBJECT (not string!)
const groqRequest = {
  model: "llama-3.3-70b-versatile",
  messages: [
    {
      role: "system",
      content: "You are a scheduling AI assistant. Analyze available time slots and recommend the TOP 3 BEST times for a meeting. Consider: 1) Morning slots (9-11am) are best for productivity, 2) Avoid lunch hours (12-1pm), 3) Mid-week (Tue-Thu) preferred over Mon/Fri, 4) Earlier dates better. Respond ONLY with valid JSON (no markdown): {\"recommendations\": [{\"date\": \"2024-12-16\", \"time\": \"09:00\", \"dayOfWeek\": \"Monday\", \"reason\": \"Best morning slot\", \"score\": 95}], \"summary\": \"I recommend these times...\"}"
    },
    {
      role: "user",
      content: `Available time slots:\n${JSON.stringify(sampleSlots, null, 2)}\n\nPlease recommend the TOP 3 best slots with reasons.`
    }
  ],
  temperature: 0.7,
  max_tokens: 1000
};

return {
  json: {
    groqRequest: groqRequest,
    allSlots: data.freeSlots,
    totalSlots: data.totalFreeSlots,
    parameters: data.parameters
  }
};

const aiData = $input.first().json;
const preparedData = $('Prepare AI Prompt').first().json;

let recommendations = [];
let aiSummary = '';

try {
  const aiResponse = aiData.choices[0].message.content;
  const cleaned = aiResponse.replace(/```json\n?|```/g, '').trim();
  const parsed = JSON.parse(cleaned);

  recommendations = parsed.recommendations || [];
  aiSummary = parsed.summary || 'AI recommendations generated.';
} catch (error) {
  recommendations = preparedData.allSlots.slice(0, 3).map((slot, i) => ({
    ...slot,
    reason: 'Available time slot',
    score: 85 - (i * 5)
  }));
  aiSummary = 'Showing first available slots.';
}

return {
  json: {
    success: true,
    aiPowered: true,
    totalFreeSlots: preparedData.totalSlots,
    topRecommendations: recommendations,
    aiSummary: aiSummary,
    allSlots: preparedData.allSlots,
    parameters: preparedData.parameters
  }
};

// Get raw input
const raw = $input.first().json;

// Normalize possible payload locations
const body =
  raw.body && Object.keys(raw.body).length > 0
    ? raw.body
    : raw;

// Normalize slot
const slotStart = body.slotStart || body.startTime || body.start;
const slotEnd = body.slotEnd || body.endTime || body.end;

// Normalize guest email
const guestEmail =
  body.guestEmail ||
  (Array.isArray(body.attendees) ? body.attendees[0] : null);

// Normalize guest name
const guestName =
  body.guestName ||
  (body.meetingTitle
    ? body.meetingTitle.replace(/^Meeting with\s*/i, '')
    : body.title
      ? body.title.replace(/^Meeting with\s*/i, '')
      : 'Guest');

// Validate required fields
if (!slotStart || !slotEnd) {
  throw new Error('Missing slotStart or slotEnd');
}

if (!guestEmail) {
  throw new Error('Missing guest information');
}

// Validate email format
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
if (!emailRegex.test(guestEmail)) {
  throw new Error('Invalid email format');
}

// Return normalized output
return {
  json: {
    calendarId: body.calendarId || 'primary',
    slotStart,
    slotEnd,
    guestEmail,
    guestName,
    meetingTitle:
      body.meetingTitle ||
      body.title ||
      `Meeting with ${guestName}`,
    meetingDescription:
      body.meetingDescription ||
      body.description ||
      'Scheduled via AI Calendar',
    timezone: body.timezone || 'UTC'
  }
};

const event = $input.first().json;
const bookingData = $('Validate Booking').first().json;

return {
  json: {
    success: true,
    message: 'Booking confirmed!',
    booking: {
      eventId: event.id,
      htmlLink: event.htmlLink,
      title: event.summary,
      startTime: event.start.dateTime,
      endTime: event.end.dateTime,
      guest: {
        name: bookingData.guestName,
        email: bookingData.guestEmail
      },
      status: event.status
    }
  }
};

const body = $input.first().json.body || {};

if (!body.eventId) {
  throw new Error('Missing eventId');
}

return {
  json: {
    calendarId: body.calendarId || 'primary',
    eventId: body.eventId,
    reason: body.reason || 'Cancelled by user'
  }
};

const eventDetails = $('Get Event Details').first().json;
const cancelData = $('Validate Cancel Request').first().json;

return {
  json: {
    success: true,
    message: 'Booking cancelled successfully',
    cancelledEvent: {
      eventId: cancelData.eventId,
      title: eventDetails.summary || 'N/A',
      startTime: eventDetails.start?.dateTime || 'N/A',
      endTime: eventDetails.end?.dateTime || 'N/A',
      reason: cancelData.reason,
      cancelledAt: new Date().toISOString()
    }
  }
};
